<script setup lang="ts">
// Site-wide SEO: canonical URL, Open Graph and Twitter tags, and the per-page OG image
// (public/og/<slug>.png, generated by scripts/og.mjs). Pages set their own title/description.
const SITE = 'https://vedunov.com'
const route = useRoute()
const { lang, t } = useLang()
const path = computed(() => (route.path.replace(/\/$/, '') || '/'))
// The same page in the other language, for hreflang.
const base = computed(() => stripLang(path.value))
const ogSlug = computed(() => {
  if (base.value === '/') return 'home'
  const m = base.value.match(/^\/(?:work\/)?([\w-]+)$/)
  return m ? m[1] : 'home'
})

useHead({
  // Functions can't live in nuxt.config's app.head (it's serialised), so the template is set here.
  htmlAttrs: { lang: () => (lang.value === 'de' ? 'de-CH' : 'en') },
  titleTemplate: (title?: string) => (title ? `${title} · Stepan Vedunov` : `Stepan Vedunov · ${t('site.tagline')}`),
  link: [
    { rel: 'canonical', href: () => SITE + path.value },
    { rel: 'alternate', hreflang: 'en', href: () => SITE + base.value },
    { rel: 'alternate', hreflang: 'de-CH', href: () => SITE + withLang(base.value, 'de') },
    { rel: 'alternate', hreflang: 'x-default', href: () => SITE + base.value },
  ],
  meta: [{ name: 'author', content: 'Stepan Vedunov' }],
})
useSeoMeta({
  ogSiteName: 'Stepan Vedunov',
  ogType: () => (path.value.startsWith('/work/') ? 'article' : 'website'),
  ogUrl: () => SITE + path.value,
  ogImage: () => `${SITE}/og/${ogSlug.value}.png`,
  ogImageWidth: 1200,
  ogImageHeight: 630,
  ogImageAlt: () => `Stepan Vedunov, ${t('site.tagline')}`,
  ogLocale: () => (lang.value === 'de' ? 'de_CH' : 'en_GB'),
  twitterCard: 'summary_large_image',
})
</script>

<template>
  <NuxtLayout>
    <NuxtPage />
  </NuxtLayout>
</template>
